157	    /**
158	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
159	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
160	     * left and separated by spaces (for example {@code '+61412345678'} renders as
161	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
162	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
163	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
164	     * recognized country code. This is the single definition of an owner's human-readable telephone.
165	     *
166	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
167	     */
168	    @Transient
169	    public String getTelephoneDisplay() {
170	        if (this.telephone == null) {
171	            return null;
172	        }
173	        String countryCode = countryCodeOf(this.telephone);
174	        if (countryCode == null) {
175	            return this.telephone;
176	        }
177	        String national = this.telephone.substring(1 + countryCode.length());
178	        StringBuilder display = new StringBuilder("+").append(countryCode);
179	        for (int i = 0; i < national.length(); i += 3) {
180	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
181	        }
182	        return display.toString();
183	    }
