265	    /**
266	     * Builds the derived identity key that consolidates all owner duplicate detection into a
267	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
268	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
269	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
270	     * equal, so a difference in any of the three parts (for example two household mates with
271	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
272	     *
273	     * @param telephone the normalized E.164 telephone
274	     * @param email the lower-cased email, or {@code null} when none
275	     * @param householdId the shared household identifier, or {@code null} when none
276	     * @return the derived identity key
277	     */
278	    public static String identityKey(String telephone, String email, String householdId) {
279	        return (telephone == null ? "" : telephone) + "|"
280	            + (email == null ? "" : email) + "|"
281	            + (householdId == null ? "" : householdId);
282	    }
283	
284	    /**
285	     * Returns this owner's derived identity key, see
286	     * {@link #identityKey(String, String, String)}.
287	     *
288	     * @return the derived identity key for this owner
289	     */
290	    @Transient
291	    public String getIdentityKey() {
292	        return identityKey(this.telephone, this.email, this.householdId);
293	    }
294	
295	    /**
296	     * Fixed telephone country-code table: the exact national-number length (the count of digits
297	     * following the country code) each country code this application recognizes admits
298	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
299	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
300	     */
301	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
302	
303	    /**
304	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
305	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
306	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
307	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
308	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
309	     * no recognized country code. This is the single definition of how an E.164 telephone splits
310	     * from its country code, shared by every rule that reasons about a telephone's country code.
311	     *
312	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
313	     * @return the recognized country-code digits, or {@code null} when none is recognized
314	     */
315	    public static String countryCodeOf(String telephone) {
316	        if (telephone == null || !telephone.startsWith("+")) {
317	            return null;
318	        }
319	        String digits = telephone.substring(1);
320	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
321	            .filter(digits::startsWith)
322	            .max(Comparator.comparingInt(String::length))
323	            .orElse(null);
324	    }
325	
326	    /**
327	     * Resolves the exact national-number length (the count of digits following the country code) a
328	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
329	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
330	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
331	     * per-country length rule). This is the single definition of the per-country national-number
332	     * lengths, shared by every rule that relates a telephone's national number to its country code.
333	     *
334	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
335	     * @return the required national-number length, or {@code null} when the code is not recognized
336	     */
337	    public static Integer nationalNumberLength(String countryCode) {
338	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
339	    }
340	
341	    /**
342	     * Fixed city-to-region table: the canonical region each known city belongs to
343	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
344	     * absent from this table has no known region.
345	     */
346	    private static final Map<String, String> CITY_REGIONS = Map.of(
347	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
348	
349	    /**
350	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
351	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
352	     * region string, or {@code null} when the city has no known region. This is the single
353	     * definition of the city-to-region mapping, shared by every rule that derives a region
354	     * from an owner's city.
355	     *
356	     * @param city the city to resolve
357	     * @return the canonical region, or {@code null} when the city has no known region
358	     */
359	    public static String regionForCity(String city) {
360	        return CITY_REGIONS.get(city);
361	    }
362	
363	    /**
364	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
365	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
366	     * A region absent from this table has no fixed range.
367	     */
368	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
369	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
370	
371	    /**
372	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
373	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
374	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
375	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
376	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
377	     *
378	     * @param region the region to resolve, or {@code null}
379	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
380	     */
381	    public static int[] postcodeRangeForRegion(String region) {
382	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
383	    }
384	
385	    /**
386	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
387	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
388	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
389	     * value, or falls in no known range. This is the single definition of the postcode-to-region
390	     * mapping, shared by every rule that derives a region from a postcode.
391	     *
392	     * @param postcode the postcode to resolve
393	     * @return the canonical region, or {@code null} when the postcode maps to no known region
394	     */
395	    public static String regionForPostcode(String postcode) {
396	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
397	            return null;
398	        }
399	        int value = Integer.parseInt(postcode);
400	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
401	            int[] range = entry.getValue();
402	            if (value >= range[0] && value <= range[1]) {
403	                return entry.getKey();
404	            }
405	        }
406	        return null;
407	    }
408	
409	    /**
410	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
411	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
412	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
413	     * range does derivation fall back to the fixed city-to-region table (see
414	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
415	     * resolves to a known region. This is the single definition of an owner's region, shared by
416	     * every rule that derives a region from an owner.
417	     *
418	     * @return the owner's canonical region, or {@code null} when it has no known region
419	     */
420	    @Transient
421	    public String getRegion() {
422	        String region = regionForPostcode(this.postcode);
423	        return region != null ? region : regionForCity(this.city);
424	    }
425	
426	    /**
427	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
428	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
429	     * owner "having an email", shared by every rule that turns email presence into a derived value
430	     * (its membership factor and its {@code contactPreference}).
431	     *
432	     * @param email the owner's email, or {@code null}
433	     * @return {@code true} when the email is present and not blank
434	     */
435	    public static boolean hasEmail(String email) {
436	        return email != null && !email.isBlank();
437	    }
438	
439	    /**
440	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
441	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
442	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
443	     * every rule that rewards an owner for being unique by name.
444	     *
445	     * @param namesakeCount the owner's namesake count, or {@code null}
446	     * @return {@code true} when the owner is known to have no namesakes
447	     */
448	    public static boolean hasNoNamesakes(Integer namesakeCount) {
449	        return namesakeCount != null && namesakeCount == 0;
450	    }
451	
452	    /**
453	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
454	     * {@code asOf}: the whole number of days between the two dates exceeds {@code 365}. Returns
455	     * {@code false} when {@code registrationDate} is absent, so the owner has no derivable tenure;
456	     * because a newly created owner has zero tenure, it never counts as long-tenured. This is the
457	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
458	     * an owner for tenure beyond a year.
459	     *
460	     * @param registrationDate the owner's registration date, or {@code null}
461	     * @param asOf the date the tenure is measured against
462	     * @return {@code true} when the owner's tenure exceeds 365 days
463	     */
464	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
465	        return registrationDate != null && ChronoUnit.DAYS.between(registrationDate, asOf) > 365;
466	    }
467	
468	    /**
469	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
470	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
471	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
472	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
473	     *
474	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
475	     * @return {@code true} when the owner is known to belong to a household of three or more
476	     */
477	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
478	        return householdMemberCount != null && householdMemberCount >= 3;
479	    }
480	
481	    /**
482	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
483	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
484	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
485	     * {@code 3} when the owner's tenure exceeds 365 days. Because a newly created owner has zero
486	     * tenure, the tenure points are never awarded on creation. This is the single source the
487	     * membership level is derived from (see {@link #getMembershipLevel()}).
488	     *
489	     * @return the owner's membership points
490	     */
491	    @Transient
492	    public Integer getMembershipPoints() {
493	        LocalDate today = LocalDate.now();
494	        int points = 0;
495	        if (hasEmail(this.email)) {
496	            points += 2;
497	        }
498	        if (hasNoNamesakes(this.namesakeCount)) {
499	            points += 1;
500	        }
501	        if (hasLargeHousehold(this.householdMemberCount)) {
502	            points += 2;
503	        }
504	        if (hasLongTenure(this.registrationDate, today)) {
505	            points += 3;
506	        }
507	        return points;
508	    }
509	
510	    /**
511	     * Returns this owner's numeric membership level, derived from its membership points (see
512	     * {@link #getMembershipPoints()}): {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
513	     * {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points.
514	     *
515	     * @return the owner's membership level
516	     */
517	    @Transient
518	    public Integer getMembershipLevel() {
519	        int points = getMembershipPoints();
520	        if (points >= 6) {
521	            return 4;
522	        }
523	        if (points >= 4) {
524	            return 3;
525	        }
526	        if (points >= 2) {
527	            return 2;
528	        }
529	        return 1;
530	    }
531	
532	    /**
533	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
534	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
535	     * {@code null} when the owner has no customer code or registration date.
536	     *
537	     * @return the owner's membership number, or {@code null} when it cannot be derived
538	     */
539	    @Transient
540	    public String getMembershipNumber() {
541	        if (this.customerCode == null || this.registrationDate == null) {
542	            return null;
543	        }
544	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
545	    }
546	
547	    /**
548	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
549	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
550	     *
551	     * @return the owner's check digit, or {@code null} when it has no customer code
552	     */
553	    @Transient
554	    public Integer getCheckDigit() {
555	        if (this.customerCode == null) {
556	            return null;
557	        }
558	        String code = this.customerCode;
559	        int sum = 0;
560	        boolean dbl = true;
561	        for (int i = code.length() - 1; i >= 0; i--) {
562	            char c = code.charAt(i);
563	            if (c < '0' || c > '9') {
564	                continue;
565	            }
566	            int d = c - '0';
567	            if (dbl) {
568	                d *= 2;
569	                if (d > 9) {
570	                    d -= 9;
571	                }
572	            }
573	            sum += d;
574	            dbl = !dbl;
575	        }
576	        return (10 - (sum % 10)) % 10;
577	    }
578	
579	    /**
580	     * Returns this owner's age band, derived from {@code birthDate} computed against
581	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
582	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
583	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
584	     * band cannot be derived. This is the single definition of an owner's age band.
585	     *
586	     * @return the owner's age band, or {@code null} when it cannot be derived
587	     */
588	    @Transient
589	    public String getAgeBand() {
590	        if (this.birthDate == null || this.registrationDate == null) {
591	            return null;
592	        }
593	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
594	        if (age < 18) {
595	            return "MINOR";
596	        }
597	        if (age < 65) {
598	            return "ADULT";
599	        }
600	        return "SENIOR";
601	    }
