613	
614	    public List<Pet> getPets() {
615	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
616	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
617	        return Collections.unmodifiableList(sortedPets);
618	    }
619	
620	    public void setPets(List<Pet> pets) {
621	        this.pets = new HashSet<>(pets);
622	    }
623	
624	    public void addPet(Pet pet) {
625	        getPetsInternal().add(pet);
626	        pet.setOwner(this);
627	    }
628	
629	    /**
630	     * Return the Pet with the given name, or null if none found for this Owner.
631	     *
632	     * @param name to test
633	     * @return true if pet name is already in use
634	     */
635	    public Pet getPet(String name) {
636	        return getPet(name, false);
637	    }
638	
639	    /**
640	     * Return the Pet with the given name, or null if none found for this Owner.
641	     *
642	     * @param name to test
643	     * @return true if pet name is already in use
644	     */
645	    public Pet getPet(String name, boolean ignoreNew) {
646	        name = name.toLowerCase();
647	        for (Pet pet : getPetsInternal()) {
648	            if (!ignoreNew || !pet.isNew()) {
649	                String compName = pet.getName();
650	                compName = compName.toLowerCase();
651	                if (compName.equals(name)) {
652	                    return pet;
653	                }
654	            }
655	        }
656	        return null;
657	    }
