61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
113	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
120	        prepareNewOwner(ownerFieldsDto, registrationDate);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setRegistrationDate(registrationDate);
124	        owner.setCustomerCode(customerCodeFor(owner));
125	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
126	        assignHousehold(owner);
127	        applyPossibleDuplicate(owner, ownerFieldsDto);
128	        this.clinicService.saveOwner(owner);
129	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
130	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
131	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
132	            owner.getMembershipLevel(), owner.getMembershipNumber());
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTitle(ownerFieldsDto.getTitle());
152	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
153	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        this.clinicService.saveOwner(currentOwner);
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        this.clinicService.deleteOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
237	     * The address is normalized in place (so a required-field check that follows rejects an
238	     * address blank after normalization), the required fields are checked, the telephone and
239	     * email are normalized in place, and the resulting owner is rejected when its derived
240	     * identity key already belongs to another owner. Each rule
241	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
242	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
243	     * to be mapped and saved.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields, normalized in place
246	     */
247	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
248	        applyAddress(ownerFieldsDto);
249	        validateRequiredFields(ownerFieldsDto);
250	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
251	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
252	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
253	        rejectDuplicateIdentity(ownerFieldsDto);
254	        rejectCityAtCapacity(ownerFieldsDto.getCity());
255	        rejectDailyLimitExceeded(registrationDate);
256	    }
257	
258	    /**
259	     * Applies an owner's address to the submitted fields, normalizing it in place into the
260	     * canonical form stored and returned for the owner. This is the single intake step that owns
261	     * how a submitted address becomes an owner's stored address: it delegates every transform to
262	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
263	     * the results back onto {@code ownerFieldsDto}.
264	     *
265	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
266	     * is present the two structured lines are normalized in place and the flat {@code address} is
267	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
268	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
269	     * every rule that later reads {@code address} sees the structured value. When no structured
270	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
271	     * backward compatibility.
272	     *
273	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
274	     * blank after normalization in either form is rejected by the required-field check that
275	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
276	     * list of named intake steps and gives address handling one place to grow.
277	     *
278	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
279	     */
280	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
281	        String line1 = ownerFieldsDto.getAddressLine1();
282	        if (line1 != null && !line1.isBlank()) {
283	            String normalizedLine1 = normalizeAddress(line1);
284	            ownerFieldsDto.setAddressLine1(normalizedLine1);
285	            String line2 = ownerFieldsDto.getAddressLine2();
286	            if (line2 != null && !line2.isBlank()) {
287	                String normalizedLine2 = normalizeAddress(line2);
288	                ownerFieldsDto.setAddressLine2(normalizedLine2);
289	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
290	            } else {
291	                ownerFieldsDto.setAddressLine2(null);
292	                ownerFieldsDto.setAddress(normalizedLine1);
293	            }
294	        } else {
295	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
296	        }
297	    }
298	
299	    /**
300	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
301	     * falls on a business day. The date supplied on the request is used when present, otherwise the
302	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
303	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
304	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
305	     * membership number's year segment, the per-day create limit) is computed against.
306	     *
307	     * A supplied registration date later than the server's current date is rejected with an
308	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
309	     *
310	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
311	     * @return the effective registration date rolled forward to the next business day
312	     */
313	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
314	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
315	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
316	            throw new InvalidFieldsException(List.of("registrationDate"));
317	        }
318	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
319	        return toBusinessDay(effective);
320	    }
321	
322	    /**
323	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
324	     * following Monday, while a weekday is returned unchanged.
325	     *
326	     * @param date the date to adjust
327	     * @return the same date when it is a weekday, otherwise the next Monday
328	     */
329	    private LocalDate toBusinessDay(LocalDate date) {
330	        java.time.DayOfWeek day = date.getDayOfWeek();
331	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
332	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
333	        }
334	        return date;
335	    }
336	
337	    /**
338	     * The maximum number of owners that may be created on a single day. Once this many owners
339	     * already carry today's {@code registrationDate}, no further owner may be created today.
340	     */
341	    private static final long DAILY_OWNER_LIMIT = 100L;
342	
343	    /**
344	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
345	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
346	     * date the new owner would be stored with, so owners are capped per business day. When the limit
347	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
348	     * advice renders as a 429 Too Many Requests response.
349	     *
350	     * @param registrationDate the adjusted business-day registration date of the owner being created
351	     */
352	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
353	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
354	            throw new DailyOwnerLimitExceededException(registrationDate);
355	        }
356	    }
357	
358	    /**
359	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
360	     * given date. This is the single definition of the per-day owner count, shared by the per-day
361	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
362	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
363	     *
364	     * @param registrationDate the adjusted business-day registration date to count owners against
365	     * @return the number of existing owners carrying that registration date
366	     */
367	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
368	        return this.clinicService.findAllOwners().stream()
369	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
370	            .count();
371	    }
372	
373	    /**
374	     * The number of owners that may carry a single day's {@code registrationDate} before that day
375	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
376	     * the create and read responses report {@code bulkSignupWarning} true for that date.
377	     */
378	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
379	
380	    /**
381	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
382	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
383	     * count is taken against the same adjusted date owners are stored with, mirroring the
384	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
385	     *
386	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
387	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
388	     */
389	    private boolean bulkSignupWarning(LocalDate registrationDate) {
390	        if (registrationDate == null) {
391	            return false;
392	        }
393	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
394	    }
395	
396	    /**
397	     * The maximum number of owners a single city may hold. Once a city already contains this
398	     * many owners, no further owner may be created in it.
399	     */
400	    private static final long CITY_OWNER_CAPACITY = 50L;
401	
402	    /**
403	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
404	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
405	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
406	     * which the exception advice renders as a 409 Conflict response.
407	     *
408	     * @param city the city of the owner being created
409	     */
410	    private void rejectCityAtCapacity(String city) {
411	        long count = this.clinicService.findAllOwners().stream()
412	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
413	            .count();
414	        if (count >= CITY_OWNER_CAPACITY) {
415	            throw new CityCapacityExceededException(city);
416	        }
417	    }
418	
419	    /**
420	     * Builds the customer code assigned to a newly created owner. The code is formatted as
421	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
422	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
423	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
424	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
425	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
426	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
427	     * identity scheme needs.
428	     *
429	     * @param owner the owner being created, whose fields the code is derived from
430	     * @return the formatted customer code
431	     */
432	    private String customerCodeFor(Owner owner) {
433	        String region = owner.getRegion();
434	        String regionCode = region != null ? region : "UNKNOWN";
435	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
436	        return deduplicateCustomerCode(regionCode + "-" + hash8);
437	    }
438	
439	    /**
440	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
441	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
442	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
443	     *
444	     * @param baseCode the customer code computed for the owner being created
445	     * @return the base code when it is already unique, otherwise the de-duplicated code
446	     */
447	    private String deduplicateCustomerCode(String baseCode) {
448	        Set<String> existing = this.clinicService.findAllOwners().stream()
449	            .map(Owner::getCustomerCode)
450	            .filter(Objects::nonNull)
451	            .collect(Collectors.toSet());
452	        if (!existing.contains(baseCode)) {
453	            return baseCode;
454	        }
455	        int n = 2;
456	        while (existing.contains(baseCode + "-" + n)) {
457	            n++;
458	        }
459	        return baseCode + "-" + n;
460	    }
461	
462	    /**
463	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
464	     * with the owner being created, compared case-insensitively. The count is taken before the
465	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
466	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
467	     *
468	     * @param firstName the first name of the owner being created
469	     * @param lastName the last name of the owner being created
470	     * @return the number of pre-existing owners sharing the same first and last name
471	     */
472	    private int countNamesakes(String firstName, String lastName) {
473	        return (int) this.clinicService.findAllOwners().stream()
474	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
475	                && lastName.equalsIgnoreCase(existing.getLastName()))
476	            .count();
477	    }
478	
479	    /**
480	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
481	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
482	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
483	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
484	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
485	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
486	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
487	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
488	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
489	     * postcode and is never a possible duplicate.
490	     *
491	     * @param owner the owner being created, already carrying its normalized telephone and postcode
492	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
493	     */
494	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
495	        owner.setPossibleDuplicate(false);
496	        owner.setPossibleDuplicateOf(null);
497	        if (sharesHousehold(ownerFieldsDto)) {
498	            return;
499	        }
500	        findPossibleDuplicate(owner).ifPresent(existing -> {
501	            owner.setPossibleDuplicate(true);
502	            owner.setPossibleDuplicateOf(existing.getId());
503	        });
504	    }
505	
506	    /**
507	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
508	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
509	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
510	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
511	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
512	     * {@link java.util.Optional#empty()} is returned.
513	     *
514	     * @param owner the owner being created, already carrying its normalized telephone and postcode
515	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
516	     */
517	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
518	        if (owner.getPostcode() == null) {
519	            return java.util.Optional.empty();
520	        }
521	        return this.clinicService.findAllOwners().stream()
522	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
523	                && owner.getPostcode().equals(existing.getPostcode())
524	                && !owner.getTelephone().equals(existing.getTelephone()))
525	            .findFirst();
526	    }
527	
528	    /**
529	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
530	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
531	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
532	     * the names of every offending field, which the exception advice renders as a 400 response
533	     * with an {@code errors} array.
534	     *
535	     * @param ownerFieldsDto the submitted owner fields
536	     */
537	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
538	        List<String> missing = new ArrayList<>();
539	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
540	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
541	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
542	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
543	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
544	        if (!missing.isEmpty()) {
545	            throw new RequiredFieldsMissingException(missing);
546	        }
547	    }
548	
549	    private void addIfBlank(List<String> missing, String fieldName, String value) {
550	        if (value == null || value.isBlank()) {
551	            missing.add(fieldName);
552	        }
553	    }
554	
555	    /**
556	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
557	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
558	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
559	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
560	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
561	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
562	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
563	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
564	     *
565	     * @param telephone the submitted telephone value
566	     * @return the normalized E.164 telephone
567	     */
568	    private String normalizeTelephone(String telephone) {
569	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
570	        String e164;
571	        if (cleaned.startsWith("+")) {
572	            e164 = "+" + cleaned.substring(1);
573	        } else {
574	            String national = cleaned;
575	            if (national.startsWith("0")) {
576	                national = national.substring(1);
577	            }
578	            e164 = "+61" + national;
579	        }
580	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
581	            throw new InvalidFieldsException(List.of("telephone"));
582	        }
583	        validateNationalNumberLength(e164);
584	        return e164;
585	    }
586	
587	    /**
588	     * Validates the national-number length of an already syntactically valid E.164 telephone
589	     * against its country code. When the number carries a country code this application recognizes
590	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
591	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
592	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
593	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
594	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
595	     * that is not recognized carries no per-country length rule and is left to the general
596	     * 8-to-15-digit E.164 check.
597	     *
598	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
599	     */
600	    private void validateNationalNumberLength(String e164) {
601	        String countryCode = Owner.countryCodeOf(e164);
602	        if (countryCode == null) {
603	            return;
604	        }
605	        int nationalLength = e164.length() - 1 - countryCode.length();
606	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
607	            throw new InvalidFieldsException(List.of("telephone"));
608	        }
609	    }
610	
611	    /**
612	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
613	     * and a domain containing at least one dot, none of the parts holding whitespace or a
614	     * second {@code @}.
615	     */
616	    private static final java.util.regex.Pattern EMAIL_PATTERN =
617	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
618	
619	    /**
620	     * Disposable email domains an owner may not register with. An email whose domain (compared
621	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
622	     */
623	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
624	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
625	
626	    /**
627	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
628	     * accepted and returned unchanged. When present it must be a syntactically valid address
629	     * whose domain is not on the disposable-domain blocklist (see
630	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
631	     * present but syntactically invalid or on a disposable domain an
632	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
633	     * response naming the {@code email} field.
634	     *
635	     * @param email the submitted email value, or {@code null} when omitted
636	     * @return the lower-cased email, or {@code null} when none was supplied
637	     */
638	    private String normalizeEmail(String email) {
639	        if (email == null) {
640	            return null;
641	        }
642	        String trimmed = email.trim();
643	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
644	            throw new InvalidFieldsException(List.of("email"));
645	        }
646	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
647	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
648	            throw new InvalidFieldsException(List.of("email"));
649	        }
650	        return canonicalEmail(trimmed);
651	    }
652	
653	    /**
654	     * Reduces an email to the canonical form used both to store it and to compare it against
655	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
656	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
657	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
658	     * value read back off an existing owner without risk of rejecting it. This is the single
659	     * definition of email identity: two emails denote the same address exactly when they
660	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
661	     * an email already on an existing owner can be compared for equality after both pass through
662	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
663	     *
664	     * @param email the email to canonicalize, or {@code null} when none was supplied
665	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
666	     */
667	    private String canonicalEmail(String email) {
668	        if (email == null) {
669	            return null;
670	        }
671	        return email.trim().toLowerCase(java.util.Locale.ROOT);
672	    }
673	
674	    /**
675	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
676	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
677	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
678	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
679	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
680	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
681	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
682	     * 400 response naming the {@code postcode} field.
683	     *
684	     * @param postcode the submitted postcode, or {@code null} when omitted
685	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
686	     */
687	    private void validatePostcode(String postcode, String city) {
688	        if (postcode == null) {
689	            return;
690	        }
691	        if (!postcode.matches("^[0-9]{4}$")) {
692	            throw new InvalidFieldsException(List.of("postcode"));
693	        }
694	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
695	        if (range != null) {
696	            int value = Integer.parseInt(postcode);
697	            if (value < range[0] || value > range[1]) {
698	                throw new InvalidFieldsException(List.of("postcode"));
699	            }
700	        }
701	    }
702	
703	    /**
704	     * Rejects a new owner that would join a household already occupied by an existing owner. The
705	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
706	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
707	     * two owners sharing a last name and postcode belong to the same household. When any existing
708	     * owner already carries that household identifier the new owner is a household duplicate and a
709	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
710	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
711	     * that household and bypasses this block, so it is created rather than rejected. An owner without
712	     * a postcode belongs to no shared household and is never a household duplicate.
713	     *
714	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
715	     */
716	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
717	        if (sharesHousehold(ownerFieldsDto)) {
718	            return;
719	        }
720	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
721	        if (householdId == null) {
722	            return;
723	        }
724	        boolean taken = this.clinicService.findAllOwners().stream()
725	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
726	        if (taken) {
727	            throw new DuplicateIdentityException(householdId);
728	        }
729	    }
730	
731	    /**
732	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
733	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
734	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
735	     * resolves to the same stable value automatically, without any explicit linking. An owner without
736	     * a postcode belongs to no shared household and is left without a household identifier.
737	     *
738	     * @param owner the newly created owner, mutated in place with its household identifier
739	     */
740	    private void assignHousehold(Owner owner) {
741	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
742	    }
743	
744	    /**
745	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
746	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
747	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
748	     * every rule that treats a declared household member differently from an independent owner.
749	     *
750	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
751	     * @return {@code true} when the request opted into sharing a household
752	     */
753	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
754	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
755	    }
756	
757	    /**
758	     * Derives the stable {@code householdId} shared by every owner in the household identified by
759	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
760	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
761	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
762	     * postcode — regardless of creation order or address — resolve to the same identifier
763	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
764	     * returned.
765	     *
766	     * @param lastName the household's last name
767	     * @param postcode the household's postcode, or {@code null} when the owner has none
768	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
769	     */
770	    private String householdIdFor(String lastName, String postcode) {
771	        if (postcode == null) {
772	            return null;
773	        }
774	        return shaHex(householdKey(lastName, postcode), 12);
775	    }
776	
777	    /**
778	     * Builds the canonical household key that identifies the household a {@code lastName} and
779	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
780	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
781	     * owner fields make up a household and how they are normalized;
782	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
783	     * owners in the same household resolve to the same key and therefore the same identifier.
784	     *
785	     * @param lastName the household's last name
786	     * @param postcode the household's postcode
787	     * @return the normalized household key
788	     */
789	    private String householdKey(String lastName, String postcode) {
790	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
791	    }
792	
793	    /**
794	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
795	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
796	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
797	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
798	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
799	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
800	     * an {@link IllegalStateException} is thrown.
801	     *
802	     * @param input the string to hash
803	     * @param hexChars the number of leading upper-case hex characters to return
804	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
805	     */
806	    private String shaHex(String input, int hexChars) {
807	        try {
808	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
809	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
810	            StringBuilder sb = new StringBuilder();
811	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
812	                sb.append(String.format("%02X", digest[i]));
813	            }
814	            return sb.substring(0, hexChars);
815	        }
816	        catch (java.security.NoSuchAlgorithmException e) {
817	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
818	        }
819	    }
820	
821	    /**
822	     * Counts the owners that belong to the household identified by the given {@code householdId},
823	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
824	     * of owners, so after a create it reflects the household's size including the newly persisted
825	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
826	     * household and yields {@code 0}.
827	     *
828	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
829	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
830	     */
831	    private int countHouseholdMembers(String householdId) {
832	        if (householdId == null) {
833	            return 0;
834	        }
835	        return (int) this.clinicService.findAllOwners().stream()
836	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
837	            .count();
838	    }
839	
840	    /**
841	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
842	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
843	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
844	     *
845	     * @param value the value to collapse, or {@code null}
846	     * @return the whitespace-collapsed value, never {@code null}
847	     */
848	    private String collapseWhitespace(String value) {
849	        if (value == null) {
850	            return "";
851	        }
852	        return value.trim().replaceAll("\\s+", " ");
853	    }
854	
855	    /**
856	     * Common street-type abbreviations expanded during address normalization, keyed by their
857	     * upper-cased token.
858	     */
859	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
860	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
861	
862	    /**
863	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
864	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
865	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
866	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
867	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
868	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
869	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
870	     * everywhere an address is stored or compared.
871	     *
872	     * @param address the submitted address value, or {@code null}
873	     * @return the normalized address, never {@code null}
874	     */
875	    private String normalizeAddress(String address) {
876	        if (address == null) {
877	            return "";
878	        }
879	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
880	        if (collapsed.isEmpty()) {
881	            return "";
882	        }
883	        String[] tokens = collapsed.split(" ");
884	        StringBuilder sb = new StringBuilder(collapsed.length());
885	        for (int i = 0; i < tokens.length; i++) {
886	            if (i > 0) {
887	                sb.append(' ');
888	            }
889	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
890	        }
891	        return sb.toString();
892	    }
893	}
